SELECT last_seen, source, title, summary_head, matched_sectors, url
FROM m_news
WHERE title LIKE {{pattern}} OR summary_head LIKE {{pattern}}
ORDER BY last_seen DESC, importance_score DESC
LIMIT {{limit}}

SELECT source, COUNT(*) AS articles, SUM(CASE WHEN investment_relevant THEN 1 ELSE 0 END) AS relevant
FROM m_news
WHERE last_seen >= (SELECT MAX(last_seen) FROM m_news) - {{days}}
GROUP BY source
ORDER BY articles DESC
LIMIT {{limit}}
